 async function perform(id,action,data={}){const result=await o.invoke('rental-action',{rentalId:id,action,...data});o.closeModal();o.toast(result.payoutWarning||(result.released?'Checkout released; held credits returned.':action==='approve'?'Deposit returned and earnings added to Tool Share Credits.':'Booking updated.'));if(o.route().startsWith('/handoff/'))o.nav('/rental/'+id);await o.refresh();return result;}
 function formSubmit(selector,fn){$(selector).onsubmit=async e=>{e.preventDefault();const b=e.submitter;o.setBusy(b);try{await fn(e.target,b);}catch(err){o.toast(err.message);}finally{o.setBusy(b,false);}};}
