  dialog('Return tool','<p>'+title(r)+' · use the same item QR for return. An owner inspection follows your confirmation.</p>'+locationCard('Agreed return / drop-off',r.return_location)+'<p>Return window: '+esc(windowText(r.return_window_start,r.return_window_end))+'</p>'+scannerMarkup+
   '<form id="return-form" class="stack"><fieldset><legend>Return condition photo</legend><button type="button" id="take-condition-photo">Take condition photo</button><video id="return-camera" class="upload-preview hidden" playsinline muted></video><button type="button" id="capture-condition" class="hidden">Capture condition photo</button><label>Or choose a condition photo<input type="file" name="photo" accept="image/*"></label><img id="return-condition-preview" class="upload-preview hidden" alt="Return condition photo preview"><p id="return-photo-status" class="fine" role="status">Take or choose one photo showing the returned item. QR photos only read the item code.</p></fieldset><label>Condition note<textarea name="note" maxlength="500" placeholder="Returned clean; normal wear only."></textarea></label><label>Item link or tracking code<input name="code" value="'+esc(code)+'" placeholder="Printed code on the tool"></label><label>Handoff method<select name="handoff"><option value="scan">In-person handoff at agreed place</option><option value="dropoff">Drop-off at agreed return location</option></select></label><p class="fine">Unused reserved time is refunded to Tool Share Credits when the owner confirms the return or the review completes. Your recorded return time stops the rental clock; inspection time adds no charge. Estimated rental refund if returned now: '+money(estimated)+'. Your deposit is reviewed separately.</p><button class="primary" disabled>Submit return</button></form>');
  const form=$('#return-form'),preview=$('#return-condition-preview'),status=$('#return-photo-status'),submit=form.querySelector('button.primary');
